import { cn } from "@/lib/utils"

/**
 * Total Wireless Stepper Component
 *
 * The step indicator from the checkout flow showing progress
 * through: Plan → Phone → Cart → Checkout → Confirmation.
 *
 * Usage:
 * <Stepper
 *   steps={["Plan", "Phone", "Cart", "Checkout", "Confirm"]}
 *   currentStep={2}
 * />
 */

interface StepperProps extends React.HTMLAttributes<HTMLDivElement> {
  steps: string[]
  currentStep: number
}

function Stepper({ className, steps, currentStep, ...props }: StepperProps) {
  return (
    <div
      data-slot="stepper"
      className={cn(
        "flex items-center justify-center gap-0 py-4 px-4",
        className
      )}
      {...props}
    >
      {steps.map((step, index) => {
        const status =
          index < currentStep
            ? "complete"
            : index === currentStep
              ? "active"
              : "pending"

        return (
          <div key={step} className="flex items-center">
            {/* Step Circle */}
            <div className="flex flex-col items-center gap-1">
              <div
                className={cn(
                  "flex h-7 w-7 items-center justify-center rounded-full text-[11px] font-bold flex-shrink-0 transition-all",
                  status === "pending" &&
                    "border-2 border-tw-gray-300 bg-tw-gray-100 text-tw-gray-400",
                  status === "active" &&
                    "border-2 border-tw-navy-900 bg-tw-navy-900 text-white shadow-[0_0_0_4px_rgba(0,3,48,0.14)]",
                  status === "complete" &&
                    "border-2 border-green-600 bg-green-600 text-white"
                )}
              >
                {status === "complete" ? (
                  <svg
                    className="h-3.5 w-3.5"
                    fill="none"
                    viewBox="0 0 24 24"
                    strokeWidth={3}
                    stroke="currentColor"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      d="M4.5 12.75l6 6 9-13.5"
                    />
                  </svg>
                ) : (
                  index + 1
                )}
              </div>
              <span
                className={cn(
                  "text-[10px] font-medium whitespace-nowrap",
                  status === "active"
                    ? "text-tw-navy-900"
                    : status === "complete"
                      ? "text-green-700"
                      : "text-tw-gray-400"
                )}
              >
                {step}
              </span>
            </div>

            {/* Connector Line */}
            {index < steps.length - 1 && (
              <div
                className={cn(
                  "h-0.5 w-8 flex-shrink-0 mx-1 mb-5",
                  index < currentStep ? "bg-green-600" : "bg-tw-gray-200"
                )}
              />
            )}
          </div>
        )
      })}
    </div>
  )
}

export { Stepper }
export type { StepperProps }
